nextflow_process {

    name "Test Process KRAKENUNIQ_BUILD"
    script "../main.nf"
    process "KRAKENUNIQ_BUILD"
    config './nextflow.config'

    tag "modules"
    tag "modules_nfcore"
    tag "krakenuniq"
    tag "krakenuniq/build"
    tag "krakenuniq/download"

    setup {
        run("KRAKENUNIQ_DOWNLOAD") {
            script "../../download/main.nf"
            process {
                """
                input[0] = 'taxonomy'
                """
            }
        }
    }

    test("sarscov2 - fasta") {

        when {
            process {
                """
                ch_fastas      = Channel.fromPath(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ch_seqid2mapid = Channel.fromPath(params.modules_testdata_base_path + 'genomics/sarscov2/metagenome/seqid2taxid.map', checkIfExists: true)

                ch_input = ch_fastas
                    .combine(KRAKENUNIQ_DOWNLOAD.out.output.map{ dir -> [ dir.listFiles().toList() ] })
                    .combine(ch_seqid2mapid)
                    .map { fna, tax, map -> [ [id:'test'], fna, tax, map ] }

                input[0] = ch_input
                input[1] = false
                """
            }
        }

        then {
            def inputs          = ["timestamp", "taxdump.tar.gz", "names.dmp", "nodes.dmp"]
            def unstableOutputs = [
                "database-build.log",  // Every line has a timestamp
                "database.report.tsv", // Timestamp and test filepath on first line
                "taxDB"                // Present species and species labels change: Probably because of KRAKENUNIQ_DOWNLOAD which fetches from NCBI.
            ]

            def dbDir    = file(process.out.db.get(0).get(1))
            def allFiles = []
            dbDir.eachFileRecurse { f -> if (!f.isDirectory()) allFiles << f }

            def stableFiles   = allFiles.findAll { f -> !unstableOutputs.any { f.name.endsWith(it) } }
            def unstableFiles = allFiles.findAll { f ->  unstableOutputs.any { f.name.endsWith(it) } }
                                        .collect { it.name }

            assertAll(
                { assert process.success },
                { assert !allFiles.any { it.name in inputs } },
                { assert snapshot(
                    stableFiles.sort(),
                    unstableFiles.sort(),
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("sarscov2 - fasta - nocleanup") {

        when {
            process {
                """
                ch_fastas      = Channel.fromPath(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ch_seqid2mapid = Channel.fromPath(params.modules_testdata_base_path + 'genomics/sarscov2/metagenome/seqid2taxid.map', checkIfExists: true)

                ch_input = ch_fastas
                    .combine(KRAKENUNIQ_DOWNLOAD.out.output.map{ dir -> [ dir.listFiles().toList() ] })
                    .combine(ch_seqid2mapid)
                    .map { fna, tax, map -> [ [id:'test'], fna, tax, map ] }

                input[0] = ch_input
                input[1] = true
                """
            }
        }

        then {
            def inputs          = ["timestamp", "taxdump.tar.gz", "names.dmp", "nodes.dmp"]
            def unstableOutputs = [
                "database-build.log",  // Every line has a timestamp
                "database.report.tsv", // Timestamp and test filepath on first line
                "taxDB"                // Present species and species labels change: Probably because of KRAKENUNIQ_DOWNLOAD which fetches from NCBI.
            ]

            def dbDir    = file(process.out.db.get(0).get(1))
            def allFiles = []
            dbDir.eachFileRecurse { f -> if (!f.isDirectory()) allFiles << f }

            def stableFiles   = allFiles.findAll { f -> !unstableOutputs.any { f.name.endsWith(it) } }
            def unstableFiles = allFiles.findAll { f ->  unstableOutputs.any { f.name.endsWith(it) } }
                                        .collect { it.name }

            assertAll(
                { assert process.success },
                { assert !allFiles.any { it.name in inputs } },
                { assert snapshot(
                    stableFiles.sort(),
                    unstableFiles.sort(),
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("sarscov2 - fasta - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = [[id:'test'], [], [], []]
                input[1] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
